import tempfile
import unittest
from pathlib import Path
from validation.core.templates import PromptTemplateLoader

class TestFormattingRequirements(unittest.TestCase):
    def render(self, text, values):
        with tempfile.TemporaryDirectory() as directory:
            root = Path(directory)
            (root / 'fixture.txt').write_text(text)
            return PromptTemplateLoader(root).render('fixture.txt', values)

    def test_repr_conversion(self):
        self.assertEqual(self.render('Value: {value!r}', {'value': 'hello'}), "Value: 'hello'")

    def test_indexed_lookup(self):
        self.assertEqual(self.render('Score: {scores[first]}', {'scores': {'first': 0.75}}), 'Score: 0.75')

    def test_supplied_json_schema_keys_survive_rendering(self):
        values = dict(task_type='intent', dimensions_block='correctness', scale_min=0, scale_max=5,
                      threshold_keep=3.8, threshold_review=3.0, input_prompt='Book me a flight',
                      context_json='{}', output_text='intent=book_flight', annotations_json='{}')
        rendered = PromptTemplateLoader(Path('validation/prompts')).render('strict_json_generic.txt', values)
        self.assertIn('"dimensions": { "<dimension_name>": { "score": float, "justification": str } },', rendered)
